<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1e293b;font-size:12px}h1{color:#1d80f7}.box{border:1px solid #cbd5e1;padding:18px;margin-top:18px}.row{margin:8px 0}.total{font-size:20px;font-weight:bold;border-top:1px solid #cbd5e1;padding-top:12px}</style></head><body>
<img src="{{ $logoDataUri }}" style="max-height:70px;max-width:240px"><h1>{{ $receipt->invoice->seller_name ?: $receipt->invoice->organization->name }}</h1><p>Payment receipt</p>
<div class="box"><p><strong>Invoice:</strong> {{ $receipt->invoice->invoice_number }}</p><p><strong>Receipt date:</strong> {{ $receipt->transaction->received_at->timezone($receipt->invoice->organization->timezone)->format('M j, Y g:i A T') }}</p><p><strong>Method:</strong> {{ ucfirst($receipt->transaction->method) }}</p>@if($receipt->transaction->safe_processor_reference)<p><strong>Processor reference:</strong> {{ $receipt->transaction->safe_processor_reference }}</p>@endif<div class="row total">{{ $receipt->transaction->type === 'payment' ? 'Payment' : 'Refund' }}: ${{ number_format($receipt->transaction->amount_cents/100,2) }}</div><div class="row">Invoice total: ${{ number_format($receipt->invoice->total_cents/100,2) }}</div><div class="row">Remaining balance: ${{ number_format(max(0,$receipt->invoice->balanceCents())/100,2) }}</div></div><p>Thank you.</p></body></html>
